package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class RefundAutomaticReturnDecisionTest {
    RefundAutomaticDecisionTest fixture;RefundServiceTest f;RefundAutomaticDecision decision;RefundMoneyAuthorizations authorizations;
    @BeforeAll static void start(){RefundServiceTest.start();}
    @BeforeEach void setup(){fixture=new RefundAutomaticDecisionTest();fixture.setup();f=fixture.f;decision=fixture.decision;f.shipped();
        authorizations=new RefundMoneyAuthorizations();authorizations.refunds=f.refunds;authorizations.catalog=mock(OrderCatalog.class);decision.moneyAuthorizations=authorizations;
        RefundAutomaticReturnDecision returns=new RefundAutomaticReturnDecision();returns.refunds=f.refunds;returns.workspace=f.workspace;returns.parcels=decision.parcels;decision.returnDecisions=returns;
        f.db.update("DELETE FROM oms_refund_money_authorization WHERE company_code IN ('VERIFY','OTHER')");
    }
    @AfterEach void clear(){f.db.update("DELETE FROM oms_exchange WHERE company_code='VERIFY'");f.db.update("DELETE FROM oms_refund_money_authorization WHERE company_code IN ('VERIFY','OTHER')");f.db.update("DELETE FROM oms_order_bundle WHERE company_code='VERIFY' AND order_id=?",f.order);fixture.clear();}
    long replacement(){
        f.db.update("DELETE FROM oms_exchange WHERE company_code='VERIFY'");long original=f.db.queryForObject("SELECT id FROM oms_order_shipment_line WHERE company_code='VERIFY'",Long.class);
        long exchange=f.repo.insert("INSERT INTO oms_exchange(company_code,exchange_sn,channel_id,source_kind,source_modified,dispute_id,payload,payload_hash,order_id,platform_oid,source_shipment_line_id,requested_quantity,approved_version,state,platform_status) VALUES ('VERIFY','HH_REPLACEMENT',1,'PLATFORM',NOW(),'123456','{}','hash',?,'987654321012345679',?,5,1,'COMPLETED','5')",f.order,original);
        long line=f.repo.insert("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,business_type,exchange_id,fulfillment_round) VALUES ('VERIFY',?,'987654321012345679','B','actual replacement',5,0,'EXCHANGE',?,1)",f.order,exchange);
        long shipment=f.repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,status,created_by,business_type,exchange_id,fulfillment_round) VALUES ('VERIFY','XS_REPLACEMENT',?,'SO_REFUND',1,'987654321012345678',2,'O','R','R',5,'SHIPPED','test','EXCHANGE',?,1)",f.order,exchange);
        return f.repo.insert("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,?,'987654321012345679','B','actual replacement',5,5,2,1,'V',1,'PUBLIC_EXTRA')",shipment,line);
    }
    @Test void completedReplacementIsPhysicalReturnSourceWhileOriginalSuborderKeepsFinancialIdentity(){long actual=replacement(),id=refund("9007199254740993","5.00",1,true);assertTrue(decision.decide("VERIFY",id,policy(true,"500.00")));Map<String,Object> task=f.db.queryForMap("SELECT * FROM oms_refund_goods_task WHERE refund_id=?",id);assertEquals(actual,number(task,"shipment_line_id"));assertEquals("B",f.db.queryForObject("SELECT sku_sn FROM oms_order_line WHERE id=?",String.class,task.get("order_line_id")));assertEquals("987654321012345679",f.refunds.business("VERIFY",id,false).get("platform_oid"));}
    @Test void unfinishedReplacementCannotBeAutomaticallyReturned(){replacement();f.db.update("UPDATE oms_exchange SET state='PROCESSING',platform_status='13' WHERE company_code='VERIFY'");long id=refund("9007199254740993","5.00",1,true);assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void originalAndReplacementBothAvailableRequireExplicitPhysicalScope(){replacement();f.db.update("UPDATE oms_exchange SET requested_quantity=3 WHERE company_code='VERIFY'");long id=refund("9007199254740993","5.00",1,true);assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals("PENDING",f.refunds.business("VERIFY",id,false).get("review_state"));}
    @Test void replacementCapacityIncludesOtherExchangeClaims(){long actual=replacement();f.db.update("INSERT INTO oms_exchange(company_code,exchange_sn,channel_id,source_kind,source_modified,dispute_id,payload,payload_hash,source_shipment_line_id,requested_quantity,approved_version,state) VALUES ('VERIFY','HH_NEXT',1,'INTERNAL',NOW(),'123457','{}','hash',?,4,1,'APPROVED')",actual);long id=refund("9007199254740993","5.00",2,true);assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void concurrentRefundsCannotOverclaimCompletedReplacement()throws Exception{replacement();long a=refund("9007199254740993","5.00",3,true),b=refund("9007199254740994","5.00",3,true);Map<String,Object> p=policy(true,"500.00");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch gate=new CountDownLatch(1);try{List<Future<Boolean>> values=new ArrayList<>();for(long id:new long[]{a,b})values.add(pool.submit(()->{gate.await();try{return decision.decide("VERIFY",id,p);}catch(IllegalArgumentException rejected){return false;}}));gate.countDown();int approved=0;for(Future<Boolean> value:values)if(value.get(20,TimeUnit.SECONDS))approved++;assertEquals(1,approved);assertEquals(3,f.db.queryForObject("SELECT SUM(quantity) FROM oms_refund_goods_task WHERE state<>'CANCELED'",Integer.class));}finally{pool.shutdownNow();}}
    long refund(String rid,String fee,long quantity,boolean returns){Map<String,Object> s=f.source(1,fee,"WAIT_SELLER_AGREE"),p=parse(text(s,"jdp_response"));p.putAll(m("refund_id",rid,"num",quantity,"good_status","BUYER_RECEIVED","has_good_return",returns,"dispute_type",returns?"REFUND_AND_RETURN":"REFUND"));s.put("refund_id",rid);s.put("jdp_response",encode(m("refund",p)));return f.convert(f.ingest(s));}
    Map<String,Object> policy(boolean enabled,String limit){Map<String,Object> p=fixture.flow.policy("VERIFY",1);p.putAll(m("enabled",1,"auto_return_review",enabled?1:0,"return_review_limit",limit,"auto_difference",1));fixture.flow.save("VERIFY",1,p,"test merchant");return fixture.flow.policy("VERIFY",1);}
    Map<String,Object> authorization(long id,String amount){Map<String,Object> b=f.refunds.business("VERIFY",id,false);return m("confirmed",true,"platform_tid",b.get("platform_tid"),"platform_oid",b.get("platform_oid"),"refund_id",b.get("refund_id"),"amount",amount,"reference_sn","DIFF-AGREEMENT-1","evidence","明确的本子单差价协议；不由金额或原因推断","expires_at",LocalDateTime.now().plusDays(1).toString().substring(0,19).replace('T',' '));}
    @Test void disabledReturnRuleNeverApprovesEvenIfSmallRefundWouldOtherwiseBeAllowed(){long id=refund("9007199254740993","2.00",1,true);Map<String,Object> p=policy(false,"0.00");p.putAll(m("small_refund_enabled",1,"small_refund_limit","20.00"));assertFalse(decision.decide("VERIFY",id,p));assertEquals("PENDING",f.refunds.business("VERIFY",id,false).get("review_state"));}
    @Test void returnIsAutomaticallyAdoptedWithPhysicalReservationAndNoManualReview(){long id=refund("9007199254740993","25.00",5,true);assertTrue(decision.decide("VERIFY",id,policy(true,"500.00")));Map<String,Object> b=f.refunds.business("VERIFY",id,false);assertEquals("自动售后规则",b.get("review_by"));assertEquals("MIXED",b.get("goods_action"));assertEquals(5,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE refund_id=?",Integer.class,id));assertEquals("RETURN",f.db.queryForObject("SELECT action FROM oms_refund_goods_task WHERE refund_id=?",String.class,id));}
    @Test void partialQuantityUsesExplicitPlatformQuantity(){long id=refund("9007199254740993","5.00",1,true);assertTrue(decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals(1,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task",Integer.class));}
    @Test void excessQuantityCannotAdopt(){long id=refund("9007199254740993","5.00",6,true);assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void excessMoneyAndUncertainOutboundCannotAdopt(){long id=refund("9007199254740993","25.00",5,true);Map<String,Object> limited=policy(true,"10.00");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,limited));Map<String,Object> p=policy(true,"500.00");f.db.update("UPDATE oms_order_shipment SET status='DISPATCHING'");Map<String,Object> finalPolicy=p;assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,finalPolicy));}
    @Test void concurrentReturnsReserveSourceBeforeAnyReturnDocumentExists()throws Exception{long a=refund("9007199254740993","5.00",4,true),b=refund("9007199254740994","5.00",4,true);Map<String,Object> p=policy(true,"500.00");ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{List<Future<Boolean>> values=new ArrayList<>();for(long id:new long[]{a,b})values.add(pool.submit(()->{start.await();try{return decision.decide("VERIFY",id,p);}catch(IllegalArgumentException rejected){return false;}}));start.countDown();int approved=0;for(Future<Boolean> v:values)if(v.get(20,TimeUnit.SECONDS))approved++;assertEquals(1,approved);assertEquals(4,f.db.queryForObject("SELECT SUM(quantity) FROM oms_refund_goods_task WHERE state<>'CANCELED'",Integer.class));}finally{pool.shutdownNow();}}
    @Test void fullBundleKeepsOriginalPhysicalComposition(){long bundle=f.repo.insert("INSERT INTO oms_order_bundle(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,revision,snapshot,business_type) VALUES ('VERIFY',?,'987654321012345679','KIT','kit',1,25,1,'{}','VIRTUAL_BUNDLE')",f.order);f.db.update("UPDATE oms_order_line SET bundle_id=?,component_quantity=5 WHERE order_id=?",bundle,f.order);long id=refund("9007199254740993","25.00",1,true);assertTrue(decision.decide("VERIFY",id,policy(true,"500.00")));assertEquals(5,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE refund_id=?",Integer.class,id));}
    @Test void partialBagScopeNeverSelectsRandomContents(){long bundle=f.repo.insert("INSERT INTO oms_order_bundle(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,revision,snapshot,business_type) VALUES ('VERIFY',?,'987654321012345679','BAG','bag',2,25,1,'{}','LUCKY_BAG')",f.order);f.db.update("UPDATE oms_order_line SET bundle_id=? WHERE order_id=?",bundle,f.order);long id=refund("9007199254740993","5.00",1,true);assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,policy(true,"500.00")));}
    @Test void explicitDifferenceIsAutomaticallyApprovedAndAuthorizationIsConsumedOnce(){long id=refund("9007199254740993","2.00",1,false);Map<String,Object> a=authorizations.create("VERIFY",1,authorization(id,"2.00"),"merchant agreement");assertTrue(decision.decide("VERIFY",id,policy(false,"0.00")));Map<String,Object> b=f.refunds.business("VERIFY",id,false);assertEquals("DIFFERENCE",b.get("purpose"));assertEquals("KEEP",b.get("goods_action"));assertEquals("自动售后规则",b.get("review_by"));assertEquals("USED",authorizations.list("VERIFY",1).get(0).get("state"));assertEquals(id,number(authorizations.list("VERIFY",1).get(0),"used_refund_id"));assertThrows(IllegalArgumentException.class,()->authorizations.revoke("VERIFY",1,number(a,"id"),1,"test"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void reasonAndSmallAmountCannotBecomeDifferenceWithoutAuthorization(){long id=refund("9007199254740993","2.00",1,false);assertFalse(decision.decide("VERIFY",id,policy(false,"0.00")));assertEquals("PENDING",f.refunds.business("VERIFY",id,false).get("review_state"));}
    @Test void mismatchedAmountRevokedAndExpiredAuthorizationsCannotBeAdopted(){long id=refund("9007199254740993","2.00",1,false);Map<String,Object> a=authorizations.create("VERIFY",1,authorization(id,"3.00"),"merchant");Map<String,Object> p=policy(false,"0.00");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p));authorizations.revoke("VERIFY",1,number(a,"id"),1,"merchant");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p));f.db.update("UPDATE oms_refund_money_authorization SET state='ACTIVE',expires_at=DATE_SUB(NOW(),INTERVAL 1 DAY)");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p));}
    @Test void authorizationCannotBeOverwrittenOrReadAcrossTenant(){long id=refund("9007199254740993","2.00",1,false);Map<String,Object> input=authorization(id,"2.00"),first=authorizations.create("VERIFY",1,input,"merchant");assertEquals(number(first,"id"),number(authorizations.create("VERIFY",1,input,"merchant"),"id"));input.put("amount","3.00");assertThrows(IllegalArgumentException.class,()->authorizations.create("VERIFY",1,input,"merchant"));assertTrue(authorizations.list("OTHER",1).isEmpty());assertThrows(IllegalArgumentException.class,()->authorizations.create("OTHER",1,input,"merchant"));}
}
